import java.util.*;

public class Main {
    static class ReplicaSet {
        private final Map<String, Integer> replicaA = new HashMap<>();
        private final Map<String, Integer> replicaB = new HashMap<>();
        private final Map<String, String> lastWriter = new HashMap<>();
        private boolean replicaBLagging = false;

        void write(String client, String key, int value) {
            replicaA.put(key, value);
            lastWriter.put(key, client);
            if (!replicaBLagging) {
                replicaB.put(key, value);
            }
        }

        void setReplicaBLagging(boolean value) {
            this.replicaBLagging = value;
        }

        int strongRead(String key) {
            // Strong consistency: always read the replica guaranteed to be current.
            return replicaA.get(key);
        }

        int eventualRead(String key) {
            // Eventual consistency: might hit the lagging replica and see a stale value.
            return replicaB.getOrDefault(key, replicaA.get(key));
        }

        int readYourWrites(String client, String key) {
            // Session guarantee: route this client back to wherever it actually wrote.
            if (client.equals(lastWriter.get(key))) {
                return replicaA.get(key);
            }
            return eventualRead(key);
        }
    }

    public static void main(String[] args) {
        ReplicaSet store = new ReplicaSet();
        store.write("alice", "x", 3);

        store.setReplicaBLagging(true);
        store.write("alice", "x", 5);

        System.out.println("Strong read: " + store.strongRead("x"));
        System.out.println("Eventual read (may be stale): " + store.eventualRead("x"));
        System.out.println("Alice's read-your-writes read: " + store.readYourWrites("alice", "x"));
        System.out.println("Bob's read-your-writes read (Bob never wrote x): " + store.readYourWrites("bob", "x"));
    }
}

