class ReplicaSet:
    def __init__(self):
        self.replica_a = {}
        self.replica_b = {}
        self.last_writer = {}
        self.replica_b_lagging = False

    def write(self, client, key, value):
        self.replica_a[key] = value
        self.last_writer[key] = client
        if not self.replica_b_lagging:
            self.replica_b[key] = value

    def set_replica_b_lagging(self, value):
        self.replica_b_lagging = value

    def strong_read(self, key):
        # Strong consistency: always read the replica guaranteed to be current.
        return self.replica_a[key]

    def eventual_read(self, key):
        # Eventual consistency: might hit the lagging replica and see a stale value.
        return self.replica_b.get(key, self.replica_a.get(key))

    def read_your_writes(self, client, key):
        # Session guarantee: route this client back to wherever it actually wrote.
        if self.last_writer.get(key) == client:
            return self.replica_a[key]
        return self.eventual_read(key)


def main():
    store = ReplicaSet()
    store.write("alice", "x", 3)

    store.set_replica_b_lagging(True)
    store.write("alice", "x", 5)

    print(f"Strong read: {store.strong_read('x')}")
    print(f"Eventual read (may be stale): {store.eventual_read('x')}")
    print(f"Alice's read-your-writes read: {store.read_your_writes('alice', 'x')}")
    print(f"Bob's read-your-writes read (Bob never wrote x): {store.read_your_writes('bob', 'x')}")


if __name__ == "__main__":
    main()

