#include <iostream>
#include <string>
#include <unordered_map>
using namespace std;

class ReplicaSet {
public:
    void write(const string& client, const string& key, int value) {
        replicaA[key] = value;
        lastWriter[key] = client;
        if (!replicaBLagging) {
            replicaB[key] = value;
        }
    }

    void setReplicaBLagging(bool value) { replicaBLagging = value; }

    int strongRead(const string& key) {
        // Strong consistency: always read the replica guaranteed to be current.
        return replicaA[key];
    }

    int eventualRead(const string& key) {
        // Eventual consistency: might hit the lagging replica and see a stale value.
        auto it = replicaB.find(key);
        return it != replicaB.end() ? it->second : replicaA[key];
    }

    int readYourWrites(const string& client, const string& key) {
        // Session guarantee: route this client back to wherever it actually wrote.
        auto it = lastWriter.find(key);
        if (it != lastWriter.end() && it->second == client) {
            return replicaA[key];
        }
        return eventualRead(key);
    }

private:
    unordered_map<string, int> replicaA;
    unordered_map<string, int> replicaB;
    unordered_map<string, string> lastWriter;
    bool replicaBLagging = false;
};

int main() {
    ReplicaSet store;
    store.write("alice", "x", 3);

    store.setReplicaBLagging(true);
    store.write("alice", "x", 5);

    cout << "Strong read: " << store.strongRead("x") << endl;
    cout << "Eventual read (may be stale): " << store.eventualRead("x") << endl;
    cout << "Alice's read-your-writes read: " << store.readYourWrites("alice", "x") << endl;
    cout << "Bob's read-your-writes read (Bob never wrote x): " << store.readYourWrites("bob", "x") << endl;

    return 0;
}
